// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the payer and the amount sent
    function testFuzz_property(address payer, uint256 amount) public {
        // keep amount in a reasonable wide domain but non-zero so a receive actually increases depositsCount in the reference
        amount = bound(amount, 1, 1 ether);
        // ensure payer has funds
        vm.deal(payer, amount);

        // record previous depositsCount
        uint256 before = c.depositsCount();

        // have the payer send ETH to c via receive
        vm.prank(payer);
        // perform call with value; if it reverts the test will revert (both versions behave similarly here)
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok, "send to receive failed");

        // exactly one assertion: depositsCount is never decreased by a receive call
        uint256 after = c.depositsCount();
        assertTrue(after >= before);
    }
}

