pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address payer, uint256 amount) public {
        // keep amount reasonable but wide
        amount = bound(amount, 0, 1 ether);

        // funds to payer so it can send
        vm.deal(payer, amount);

        // record before
        uint256 beforeCount = c.depositsCount();

        // Have payer send Ether to c to invoke receive()
        vm.prank(payer);
        // call receive by sending empty calldata and value
        (bool ok, ) = address(c).call{value: amount}("");
        // require the call to have succeeded for the property to apply
        // The property: when a payment succeeds, depositsCount must not decrease.
        if (ok) {
            uint256 afterCount = c.depositsCount();
            assertTrue(afterCount >= beforeCount);
        } else {
            // if the payment failed, we still must assert something about c's state
            // In that case, depositsCount must be unchanged (call reverted before state change)
            uint256 afterCount = c.depositsCount();
            assertTrue(afterCount == beforeCount);
        }
    }
}

