pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: sender is an address that sends a nonzero amount
    function testFuzz_property(address sender, uint256 amount) public {
        // keep sender non-zero and amount within reasonable bounds but allow wide domain
        vm.assume(sender != address(0));
        amount = bound(amount, 1, type(uint256).max);

        // give sender funds and make the call to trigger receive()
        vm.deal(sender, amount);
        uint256 before = c.depositsCount();

        vm.prank(sender);
        // call receive by sending value to the contract
        (bool ok, ) = address(c).call{value: amount}("");
        // require the call succeeded in order to observe depositsCount semantics on successful receive
        vm.assume(ok);

        uint256 after = c.depositsCount();

        // General rule: when a nonzero payment is accepted (call succeeded), depositsCount must not decrease.
        // This is true for the reference contract for all admissible inputs, and the mutant that decrements
        // depositsCount on receive will violate it for some inputs; assert that after >= before.
        assertTrue(after >= before);
    }
}

