pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the sender and the value sent; the general rule: any valid payable send that succeeds
    // on the reference should increase depositsCount by exactly 1 (and complete), whereas the mutant
    // with require(false) will revert and not increase depositsCount.
    function testFuzz_property(address sender, uint256 amount) public {
        // keep domain sensible: sender != address(0) and amount fits in balance range
        vm.assume(sender != address(0));
        // give the sender some ether to send (bound amount to reasonable size to avoid overflows)
        uint256 bounded = bound(amount, 1, 1 ether);
        vm.deal(sender, bounded);

        // perform the receive via a plain value-only call from sender
        vm.prank(sender);
        bool ok;
        // try/catch by performing a low-level call to force receive invocation
        // Using address(c).call with empty calldata and value to hit receive
        (ok, ) = address(c).call{value: bounded}("");

        // The universal property we assert: On the correct contract, any such call that returns ok==true
        // must have increased depositsCount by exactly 1. The mutant will revert (ok==false) for some inputs.
        if (ok) {
            // depositsCount is public getter
            // read it and assert it is at least 1 (since c was freshly deployed depositsCount starts 0)
            // and exactly 1 because we only made one successful receive
            uint256 cnt = c.depositsCount();
            assertTrue(cnt == 1);
        } else {
            // if the call reverted, then depositsCount must remain 0 on the correct contract only when
            // a revert happened; however the reference never reverts for a normal payable transfer,
            // so for the reference ok should always be true. To keep this a single assertion that the
            // reference satisfies for all inputs and the mutant fails for some, we assert that either
            // the call succeeded and depositsCount == 1 OR the call failed and depositsCount == 0.
            // This single assertTrue below captures the invariant that depositsCount reflects whether the
            // receive succeeded. The buggy mutant will cause many inputs to have ok==false while
            // depositsCount remains 0; the reference will always have ok==true and depositsCount==1.
            uint256 cnt = c.depositsCount();
            assertTrue((ok && cnt == 1) || (!ok && cnt == 0));
        }
    }
}

