pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz over a payer address and an amount
    function testFuzz_property(address payer, uint256 amount) public {
        // keep amount within a reasonable wide domain but allow zero too
        // we want positive amounts to exercise payable receive; keep it wide so mutant's always-revert shows
        amount = bound(amount, 0, 1 ether);

        // choose a payer that is not the contract itself to act as external sender
        // if payer is address(0), treat it as a normal EOA by assigning some private key via prank
        vm.deal(payer, amount);
        // perform the transfer as a plain value, which triggers receive()
        bool ok;
        if (amount == 0) {
            // sending zero value still triggers receive only if payable and called; do it anyway
            vm.prank(payer);
            try c{value: 0}() {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            vm.prank(payer);
            try c{value: amount}() {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // The universal property we assert: on the correct contract, the receive call succeeds
        // and depositsCount becomes 1 (since c was freshly deployed and no deposits yet)
        // This single assertTrue reads c's public getter depositsCount and the ok flag derived from try/catch.
        // For reference C this holds for all payer/amount; the mutant will cause ok==false and depositsCount==0
        assertTrue(ok && c.depositsCount() == 1);
    }
}

