pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to send and an arbitrary origin address (EOA) that funds the forwarder
    function testFuzz_property(uint256 amount, address payer) public {
        // Keep amount in a practical range for fuzzing and non-zero to trigger receive
        amount = bound(amount, 1, 1 ether);
        // avoid the zero address for payer so vm.deal works well
        if (payer == address(0)) payer = address(1);

        // deploy a helper that, when told to, will forward ETH to c via a simple call (so msg.sender in C.receive is the forwarder contract)
        Forwarder f = new Forwarder();

        // fund the payer and have the payer fund the forwarder
        vm.deal(payer, amount);
        vm.startPrank(payer);
        // send ETH to forwarder so it can forward to c
        (bool okSend,) = address(f).call{value: amount}("");
        require(okSend, "funding forwarder failed");
        vm.stopPrank();

        // record depositsCount before
        uint256 before = c.depositsCount();

        // now have the forwarder forward to c; this will trigger C.receive()
        bool ok;
        try f.forwardTo{value: 0}(address(c), amount) {
            // if no revert, treat as success
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: in the correct contract, forwarding a positive amount
        // to C should succeed (ok == true) and increment depositsCount by exactly 1.
        // We observe this via c's public getter depositsCount. The mutant that always reverts on
        // receive will cause ok == false for some inputs and the assertion will fail.
        assertTrue(ok && (c.depositsCount() == before + 1));
    }
}

// Minimal adversarial forwarder: it receives ETH and can forward it to a target via a plain call.
contract Forwarder {
    // accept ETH
    receive() external payable {}

    // forward the entire balance to target
    function forwardTo(address _target, uint256 _value) external returns (bool) {
        // perform a low-level call to the target with value; this makes msg.sender in target be this contract
        (bool success,) = _target.call{value: _value}("");
        require(success, "forward failed");
        return success;
    }
}

