pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        // deploy attacker that will receive funds and reenter c.receive
        attacker = new Attacker(address(c));
    }

    // Fuzzed params: sender address and amount (wei) to send into receive
    function testFuzz_property(address sender, uint256 amount) public {
        // keep sender non-zero and not the contract itself
        vm.assume(sender != address(0));
        vm.assume(sender != address(this));
        // bound amount to a reasonable range but allow zero as well
        amount = bound(amount, 0, 1 ether);

        // Fund the sender so it can send the amount
        vm.deal(sender, amount + 1 ether);

        // record old count
        uint oldCount = c.depositsCount();

        // Arrange: if amount>0 we let sender send value directly; if amount==0, use attacker to trigger reentrancy
        if (amount == 0) {
            // make attacker the sender of an empty-value transfer, attacker will call c (reenter) in its receive
            vm.prank(address(attacker));
            // send 0 wei to c from attacker (attacker's fallback will reenter c.receive)
            (bool ok,) = address(c).call{value: 0}("");
            // we don't assert call success here; we just care about state change
            // proceed to check invariant below
        } else {
            // normal send from fuzzed sender with value amount
            vm.prank(sender);
            (bool ok,) = address(c).call{value: amount}("");
            // proceed regardless of ok
        }

        uint newCount = c.depositsCount();

        // The universal invariant: after any successful (or attempted) invocation of receive via an external caller,
        // the reference implementation always increments depositsCount by exactly 1. The buggy mutant that removed
        // the require can be forced (via reentrancy on zero-value receive) to violate this equality for some inputs.
        assertTrue(newCount == oldCount + 1);
    }
}

// Minimal adversarial helper: when it receives a call with 0 value, it will reenter c.receive to try to disturb the counting.
contract Attacker {
    address public target;
    bool public reentered;

    constructor(address _target) payable {
        target = _target;
    }

    receive() external payable {
        // Only attempt one reentry to avoid infinite loop
        if (!reentered) {
            reentered = true;
            // low-level call to trigger target.receive()
            (bool ignored,) = address(target).call{value: 0}("");
            ignored;
        }
    }
}

