pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { 
        c = new C();
        attacker = new Attacker(address(c));
    }

    // fuzzed params: attacker sends value `amount` (wei) to C via its own payable fallback which forwards to C.receive
    function testFuzz_property(uint256 amount) public {
        // keep amount within a wide but realistic range: allow zero and large values but within balanceable range
        vm.assume(amount <= type(uint256).max);

        // fund attacker with amount so it can send
        vm.deal(address(attacker), amount);

        // record depositsCount before
        uint256 before = c.depositsCount();

        // Have attacker call receive on C by using its fallback which is payable and reenters once
        // attacker will try reentrancy to exploit absence of guard in mutant; we call attacker to trigger the sequence
        attacker.trigger{value: amount}();

        // read depositsCount after
        uint256 after = c.depositsCount();

        // General rule: depositsCount must not decrease after a single external payable call
        assertTrue(after >= before);
    }
}

// Minimal adversarial helper that on first receive forwards value to C and then reenters once into C.receive
contract Attacker {
    address immutable target;
    bool reentered;
    constructor(address _target) payable {
        target = _target;
    }

    // trigger entry by sending ETH to this contract; this function will forward to C via low-level call
    function trigger() external payable {
        // forward the ETH to C using a plain call which will invoke C.receive
        (bool ok,) = target.call{value: msg.value}("");
        require(ok);
    }

    // fallback receives funds; on first receive, attempt to reenter target.receive via low-level call
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // attempt to reenter target.receive with 0 value (still a call to receive)
            // this models a reentrant adversary that can call receive again while the first call is still in progress
            // Use low-level call so it triggers receive on target
            (bool ok,) = target.call{value: 0}("");
            // ignore ok; we just attempt reentrancy
        }
    }
}

