contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller provides an amount to deposit and then
    // attempts to call withdrawAll; assert that a non-owner call reverts.
    // Parameters:
    // - depositAmt: amount of wei this test contract will send to C via receive()
    // - asOwner: if true, the test asserts withdrawAll succeeds when msg.sender == owner;
    //            if false, the test asserts withdrawAll reverts when msg.sender != owner.
    // Note: We cannot change msg.sender here; instead we rely on observable behavior
    // via revert status. To observe revert, we perform low-level call and check success.
    function checkWithdrawAll(uint depositAmt, bool expectSuccess) public payable {
        // ensure this contract has enough balance to deposit
        require(address(this).balance >= depositAmt, "insufficient balance for deposit");

        // deposit into c so it has funds to withdraw
        (bool okDeposit, ) = address(c).call{value: depositAmt}("");
        require(okDeposit, "deposit failed");

        // try to call withdrawAll on c from this caller (msg.sender is this contract's caller)
        // we capture whether the call succeeded (did not revert)
        (bool okWithdraw, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // The property: only the actual owner of c can call withdrawAll successfully.
        // In the original contract P, withdrawAll only succeeds for the owner, so
        // okWithdraw equals expectSuccess as provided by test harness.
        // In mutant M (onlyOwner inverted), this property is violated: a non-owner
        // call that should fail will succeed (or vice versa), so the assertion fails.
        assert(okWithdraw == expectSuccess);
    }

    // allow this contract to receive Ether for funding deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No precondition: caller must be the owner of c for P to accept the call.
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // On original contract P, the owner can call withdrawAll, so it should not revert.
        // We assert that this call does not revert (i.e., reverted == false).
        assert(reverted == false);
    }
    receive() external payable { }
}

