        require(msg.sender == address(this) || address(this) == c.owner());
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // On original contract P, the owner can call withdrawAll, so it should not revert.
        // We assert that this call does not revert (i.e., reverted == false).
        assert(reverted == false);
