contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // Tighten precondition: only proceed when this contract is the owner of c (checked via view)
        // or when msg.sender equals the owner of c (so the call originates from the owner).
