    function run(address caller, uint amount) public payable {
        // Tighten precondition: exclude the case where this test contract itself is the owner
        // but the provided caller parameter differs from c.owner(). Also ensure that if
        // the provided caller equals c.owner(), then msg.sender must equal c.owner() so
        // the observable behavior (owner-based access) matches the caller argument.
        require(!(msg.sender == c.owner() && caller != c.owner()) && (caller != c.owner() || msg.sender == c.owner()));
        bool reverted;
        // The call that changes c's state must be a top-level statement.
        try c.withdraw(amount) { reverted = false; } catch { reverted = true; }
        // General rule: if the caller argument is not the owner of c, then calling withdraw should revert.
        // We can observe owner via the public getter c.owner().
        assert( (caller == c.owner()) || reverted );
    }
    receive() external payable { }
}
